use crate::aap::caps::{http_client, state_rw};

/// Hosts this node's HTTPClient handle is scoped to. A request outside this set
/// would trap at the boundary and fail the whole tick, so such URLs are
/// reported as failures instead of being sent.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Key under which each call's input is recorded in the shared state store.
/// Access to the store is the `state-rw` grant approved by the platform team.
/// The graph's `with` clause for FetchFeeds should list it too.
const LAST_INPUT_KEY: &str = "last-input";

struct Node;

/// Encode a string as a JSON string literal.
fn json_string(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                let v = c as u32;
                out.push_str("\\u00");
                let hex = b"0123456789abcdef";
                out.push(hex[((v >> 4) & 0xf) as usize] as char);
                out.push(hex[(v & 0xf) as usize] as char);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

/// Serialise the subscription list as `{"urls":[...]}`.
fn encode_input(subs: &SubscriptionList) -> String {
    let mut out = String::from("{\"urls\":[");
    for (i, url) in subs.urls.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        json_string(url, &mut out);
    }
    out.push_str("]}");
    out
}

/// Extract the lowercase host of an http(s) URL, or None if the URL is not one.
fn host_of(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if lower.starts_with("https://") {
        &trimmed[8..]
    } else if lower.starts_with("http://") {
        &trimmed[7..]
    } else {
        return None;
    };
    let authority_end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    let host = match host_port.rfind(':') {
        Some(i) if !host_port.starts_with('[') => &host_port[..i],
        _ => host_port,
    };
    let host = host.trim_end_matches('.');
    if host.is_empty() {
        None
    } else {
        Some(host.to_ascii_lowercase())
    }
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => ALLOWED_HOSTS.iter().any(|a| *a == h),
        None => false,
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input received on this call. This has no effect on the output.
        state_rw::put(LAST_INPUT_KEY, &encode_input(&subscriptions));

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in this node's HTTP allowlist; not requested".to_string(),
                });
                continue;
            }
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
